48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	};
56	
57	const quotePremium = (step: QuoteStep): number => {
58	  const policyBasePremium = step.items.reduce(
59	    (sum, item) => sum + BASE_PREMIUMS[item.type],
60	    0,
61	  );
62	  return (
63	    policyBasePremium +
64	    policyBasePremium * FIRST_INSURANCE_SURCHARGE +
65	    PROCESSING_FEE
66	  );
67	};
68	
